using System.Reflection;
using TownOfHost;using TownOfHost.Modules.MainMenu;using UnityEngine;using Obj=UnityEngine.Object;
partial class Program {
 static void NoWavePlay(SeasideMainMenuPatch.HomeView view){TownOfHost.Main.DisableWaveAnimation.Value=true;view.Tick(true);Proxy("Play").OnClick.Invoke();Pump(view,25);Check(view.Page==SeasidePage.Play&&!view.Transitioning);}
 static void WavePreferenceTests(){
 Test("wave preference defaults to the existing animated path",()=>{var x=Setup();Check(!TownOfHost.Main.DisableWaveAnimation.Value);x.view.Tick(true);Proxy("Play").OnClick.Invoke();Pump(x.view,16);Check(x.view.Transitioning);x.view.Dispose();});
 Test("no wave waits for the existing press feedback before changing page",()=>{var x=Setup();TownOfHost.Main.DisableWaveAnimation.Value=true;x.view.Tick(true);Proxy("Play").OnClick.Invoke();Pump(x.view,6);Near(Motion("Play").localScale.y,.95);Check(x.view.Page==SeasidePage.Home);Pump(x.view,8);Check(x.view.Page==SeasidePage.Home);Pump(x.view,1);Check(x.view.Page==SeasidePage.Play&&!x.view.Transitioning);x.view.Dispose();});
 Test("no wave forward creates neither water mesh nor letters",()=>{var x=Setup();NoWavePlay(x.view);Check(!Obj.Objects.Any(o=>o.name=="SeasideWaveTransition"||o.name.StartsWith("WaveLetter_")));Check(x.menu.playButton.OnClick.Calls==0);x.view.Dispose();});
 Test("no wave reverse restores all fourteen hit targets",()=>{var x=Setup();NoWavePlay(x.view);Proxy("PlayBack").OnClick.Invoke();Pump(x.view,25);Check(x.view.Page==SeasidePage.Home&&!x.view.Transitioning);foreach(var target in SeasideMenuLayout.Targets)Check(Proxy(target.Id).gameObject.activeSelf);foreach(var id in SeasidePlayLayout.Ids)Check(!Proxy(id).gameObject.activeSelf);x.view.Dispose();});
 Test("no wave controller focus belongs to the visible play page",()=>{var x=Setup();NoWavePlay(x.view);var state=ControllerManager.Instance.CurrentUiState;Check(state.SelectableUiElements.Count==4&&!state.SelectableUiElements.Contains(Proxy("Play")));Check(state.CurrentSelection.gameObject.activeSelf);x.view.Dispose();});
 Test("no wave reverse restores home controller focus",()=>{var x=Setup();NoWavePlay(x.view);Proxy("PlayBack").OnClick.Invoke();Pump(x.view,25);var state=ControllerManager.Instance.CurrentUiState;Check(state.SelectableUiElements.Count==15&&state.CurrentSelection==Proxy("Play"));x.view.Dispose();});
 Test("no wave rapid play clicks do not dispatch native actions",()=>{var x=Setup();TownOfHost.Main.DisableWaveAnimation.Value=true;x.view.Tick(true);for(int i=0;i<25;i++)Proxy("Play").OnClick.Invoke();Pump(x.view,25);Check(x.view.Page==SeasidePage.Play&&!x.view.Transitioning&&x.menu.playButton.OnClick.Calls==0);x.view.Dispose();});
 foreach(var id in new[]{"PlayOnline","PlayLocal"})Test("no wave preserves native handler exactly once: "+id,()=>{var x=Setup();NoWavePlay(x.view);for(int i=0;i<10;i++)Proxy(id).OnClick.Invoke();Pump(x.view,25);Check((id=="PlayOnline"?x.menu.PlayOnlineButton:x.menu.playLocalButton).OnClick.Calls==1);x.view.Dispose();});
 Test("no wave keeps play button hover feedback",()=>{var x=Setup();NoWavePlay(x.view);Proxy("PlayBack").OnMouseOver.Invoke();Pump(x.view,15);Check(Math.Abs(Motion("PlayBack").localRotation.Z)>.01);x.view.Dispose();});
 foreach(var frames in new[]{16,35,80,135})Test("turning ON during the forward wave safely completes destination at frame "+frames,()=>{var x=Setup();x.view.Tick(true);Proxy("Play").OnClick.Invoke();Pump(x.view,frames);Check(x.view.Transitioning);TownOfHost.Main.DisableWaveAnimation.Value=true;Pump(x.view,1);Check(x.view.Page==SeasidePage.Play&&!x.view.Transitioning&&!Obj.Objects.Single(o=>o.name=="SeasideWaveTransition").activeSelf);Pump(x.view,160);Check(x.view.Page==SeasidePage.Play);x.view.Dispose();});
 Test("turning ON during reverse completes home without a residual wave",()=>{var x=Setup();EnterPlay(x.view);Proxy("PlayBack").OnClick.Invoke();Pump(x.view,30);TownOfHost.Main.DisableWaveAnimation.Value=true;Pump(x.view,1);Check(x.view.Page==SeasidePage.Home&&!x.view.Transitioning&&!Obj.Objects.Single(o=>o.name=="SeasideWaveTransition").activeSelf);x.view.Dispose();});
 Test("turning OFF affects the next navigation and restores reverse water",()=>{var x=Setup();NoWavePlay(x.view);TownOfHost.Main.DisableWaveAnimation.Value=false;Pump(x.view,2);Check(!x.view.Transitioning);Proxy("PlayBack").OnClick.Invoke();Pump(x.view,16);Check(x.view.Transitioning);var timeline=(SeasideTransition)typeof(SeasideMainMenuPatch.HomeView).GetField("transition",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(x.view);Check(timeline.Reverse);Pump(x.view,140);Check(x.view.Page==SeasidePage.Home&&!x.view.Transitioning);x.view.Dispose();});
 Test("an existing wave stays hidden during later skipped navigation",()=>{var x=Setup();EnterPlay(x.view);TownOfHost.Main.DisableWaveAnimation.Value=true;Proxy("PlayBack").OnClick.Invoke();Pump(x.view,25);Proxy("Play").OnClick.Invoke();Pump(x.view,25);Check(x.view.Page==SeasidePage.Play&&!Obj.Objects.Single(o=>o.name=="SeasideWaveTransition").activeSelf);x.view.Dispose();});
 Test("a foreign controller state still cancels instead of completing behind a modal",()=>{var x=Setup();x.view.Tick(true);Proxy("Play").OnClick.Invoke();Pump(x.view,16);ControllerManager.Instance.CurrentUiState=new();TownOfHost.Main.DisableWaveAnimation.Value=true;Pump(x.view,1);Check(!x.view.Transitioning&&x.view.Page==SeasidePage.Home);x.view.Dispose();});
 Test("hiding mid-wave cancels and the new preference applies on reopening",()=>{var x=Setup();x.view.Tick(true);Proxy("Play").OnClick.Invoke();Pump(x.view,40);x.view.Hide();TownOfHost.Main.DisableWaveAnimation.Value=true;x.view.Tick(true);Check(x.view.Visible&&x.view.Page==SeasidePage.Home);Proxy("Play").OnClick.Invoke();Pump(x.view,25);Check(x.view.Page==SeasidePage.Play&&!x.view.Transitioning);x.view.Dispose();});
 Test("no wave Escape uses the existing back press without water",()=>{var x=Setup();NoWavePlay(x.view);Input.Escape=true;Pump(x.view,25);Check(x.view.Page==SeasidePage.Home&&!x.view.Transitioning);x.view.Dispose();});
 Test("missing configuration preserves animation as a safe default",()=>{var x=Setup();TownOfHost.Main.DisableWaveAnimation=null;x.view.Tick(true);Proxy("Play").OnClick.Invoke();Pump(x.view,16);Check(x.view.Transitioning);x.view.Dispose();});
 foreach(float ratio in new[]{4f/3,16f/9,21f/9,9f/16})Test("no wave retains page geometry at aspect "+ratio,()=>{var x=Setup();Camera.main.aspect=ratio;NoWavePlay(x.view);foreach(var id in SeasidePlayLayout.Ids)Check(Proxy(id).gameObject.activeSelf);Check(Text("GameVersion").text=="v19.8a (build num: 7492)");Proxy("PlayBack").OnClick.Invoke();Pump(x.view,25);Check(x.view.Page==SeasidePage.Home);x.view.Dispose();});
 Test("no wave repeated round trips restore neutral button poses",()=>{var x=Setup();TownOfHost.Main.DisableWaveAnimation.Value=true;x.view.Tick(true);for(int i=0;i<8;i++){Proxy("Play").OnClick.Invoke();Pump(x.view,25);Check(x.view.Page==SeasidePage.Play);Neutral("Play");Proxy("PlayBack").OnClick.Invoke();Pump(x.view,25);Check(x.view.Page==SeasidePage.Home);Neutral("PlayBack");}x.view.Dispose();});
 }
}
